-- Opt-in local synthetic abuse state. Historic source counters survive account deletion.
ALTER TABLE users ADD CONSTRAINT users_abuse_trust_range CHECK(trust_level BETWEEN 0 AND 3);
CREATE TABLE abuse_storage_guard(id INTEGER PRIMARY KEY CHECK(id=1),last_time TIMESTAMPTZ,key_fingerprint TEXT CHECK(key_fingerprint ~ '^[a-f0-9]{64}$'));
INSERT INTO abuse_storage_guard(id) VALUES(1);
CREATE TABLE abuse_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,verified_contact BOOLEAN NOT NULL DEFAULT FALSE,signup_verified BOOLEAN NOT NULL DEFAULT FALSE,good_behavior INTEGER NOT NULL DEFAULT 0 CHECK(good_behavior BETWEEN 0 AND 1000000));
CREATE TABLE abuse_sources(user_key TEXT NOT NULL CHECK(user_key ~ '^[a-f0-9]{64}$'),source_kind TEXT NOT NULL CHECK(source_kind IN ('device','ip_range')),source_hash TEXT NOT NULL CHECK(source_hash ~ '^[a-f0-9]{64}$'),first_seen_at TIMESTAMPTZ NOT NULL,last_seen_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(user_key,source_kind,source_hash));
CREATE INDEX abuse_sources_cluster ON abuse_sources(source_kind,source_hash,last_seen_at);
CREATE TABLE abuse_counters(scope TEXT NOT NULL CHECK(scope IN ('user_day','user_burst','device_day','ip_day')),owner_key TEXT NOT NULL CHECK(owner_key ~ '^[a-f0-9]{64}$'),window_at TIMESTAMPTZ NOT NULL,used INTEGER NOT NULL CHECK(used BETWEEN 0 AND 1000000),PRIMARY KEY(scope,owner_key,window_at));
CREATE TABLE abuse_daily_token_counters(user_id TEXT NOT NULL REFERENCES users(id),day_at TIMESTAMPTZ NOT NULL,used_tokens BIGINT NOT NULL DEFAULT 0 CHECK(used_tokens>=0),reserved_tokens BIGINT NOT NULL DEFAULT 0 CHECK(reserved_tokens>=0),PRIMARY KEY(user_id,day_at));
CREATE TABLE abuse_challenges(id TEXT PRIMARY KEY CHECK(id ~ '^[A-Za-z0-9_-]{1,160}$'),user_key TEXT NOT NULL CHECK(user_key ~ '^[a-f0-9]{64}$'),source_key TEXT NOT NULL CHECK(source_key ~ '^[a-f0-9]{64}$'),purpose TEXT NOT NULL CHECK(purpose IN ('signup','burst')),nonce_hash TEXT NOT NULL CHECK(nonce_hash ~ '^[a-f0-9]{64}$'),difficulty INTEGER NOT NULL CHECK(difficulty BETWEEN 1 AND 20),created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,CHECK(expires_at>created_at));
CREATE TABLE abuse_admissions(request_id TEXT PRIMARY KEY CHECK(request_id ~ '^[A-Za-z0-9_-]{1,160}$'),user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,source_key TEXT NOT NULL CHECK(source_key ~ '^[a-f0-9]{64}$'),trust_level INTEGER NOT NULL CHECK(trust_level BETWEEN 0 AND 3),day_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,FOREIGN KEY(request_id,user_id) REFERENCES chat_requests(id,user_id) ON DELETE CASCADE);
CREATE TABLE abuse_moderation(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,action TEXT NOT NULL CHECK(action IN ('none','suspend','throttle','ban')),until_at TIMESTAMPTZ,reason TEXT NOT NULL CHECK(reason IN ('ACCOUNT_ABUSE','CLUSTER_RISK','AUTOMATION_RISK','REVIEW_COMPLETE','VERIFIED_LOCAL_EVIDENCE')),actor_key TEXT NOT NULL CHECK(actor_key ~ '^[a-f0-9]{64}$'),actor_role TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CHECK((action IN ('suspend','throttle') AND until_at IS NOT NULL) OR (action IN ('none','ban') AND until_at IS NULL)));
CREATE TABLE abuse_alerts(id TEXT PRIMARY KEY,source_kind TEXT NOT NULL CHECK(source_kind IN ('device','ip_range')),source_hash TEXT NOT NULL CHECK(source_hash ~ '^[a-f0-9]{64}$'),window_at TIMESTAMPTZ NOT NULL,account_count INTEGER NOT NULL CHECK(account_count BETWEEN 2 AND 1000000),rule TEXT NOT NULL CHECK(rule='ACCOUNT_CLUSTER'),created_at TIMESTAMPTZ NOT NULL,UNIQUE(source_kind,source_hash,window_at));
CREATE TABLE abuse_events(id TEXT PRIMARY KEY,actor_key TEXT NOT NULL CHECK(actor_key ~ '^[a-f0-9]{64}$'),actor_role TEXT NOT NULL,target_key TEXT NOT NULL CHECK(target_key ~ '^[a-f0-9]{64}$'),kind TEXT NOT NULL CHECK(kind IN ('SIGNUP_CHALLENGE','ADMISSION','TRUST_EVIDENCE','TRUST_CHANGED','MODERATION','MODERATION_EXPIRED')),operation_key TEXT,request_hash TEXT CHECK(request_hash ~ '^[a-f0-9]{64}$'),metadata JSONB NOT NULL CHECK(jsonb_typeof(metadata)='object' AND octet_length(metadata::text)<=2048),created_at TIMESTAMPTZ NOT NULL,UNIQUE(actor_key,operation_key));
CREATE TRIGGER abuse_events_no_change BEFORE UPDATE OR DELETE ON abuse_events FOR EACH ROW EXECUTE FUNCTION reject_append_only_change();
CREATE TRIGGER abuse_events_no_truncate BEFORE TRUNCATE ON abuse_events FOR EACH STATEMENT EXECUTE FUNCTION reject_append_only_change();
CREATE TRIGGER abuse_alerts_no_change BEFORE UPDATE OR DELETE ON abuse_alerts FOR EACH ROW EXECUTE FUNCTION reject_append_only_change();
CREATE TRIGGER abuse_alerts_no_truncate BEFORE TRUNCATE ON abuse_alerts FOR EACH STATEMENT EXECUTE FUNCTION reject_append_only_change();
